 47→    function Write-Usage {
 48→        Write-Host @"
 49→Usage: install.ps1 [-Channel stable|nightly] [-InstallDir <path>] [-NoPathUpdate]
 50→
 51→Options:
 52→  -Channel       Release channel to install (default: stable)
 53→  -InstallDir    Direct-install destination (default: `$HOME\.local\bin)
 54→  -NoPathUpdate  Do not add a direct-install destination to the user PATH
 55→  -Help, -h      Show this help message
 56→
 57→Stable installs use Scoop when it is available. Nightly installs use the
 58→verified release archive because the Scoop bucket only publishes stable builds.
 59→"@
 60→    }
