 62→    function Install-EntireWithScoop {
 63→        Write-Info "Scoop detected; installing Entire CLI with Scoop..."
 64→
 65→        $bucketOutput = & "scoop" bucket list 2>&1
 66→        $bucketExitCode = $LASTEXITCODE
 67→        if ($bucketExitCode -ne 0) {
 68→            $details = ($bucketOutput | Out-String).Trim()
 69→            throw "Failed to list Scoop buckets. $details"
 70→        }
 71→
 72→        $bucketList = $bucketOutput | Out-String
 73→        if ($bucketList -notmatch "(?im)^\s*entire(?:\s|$)") {
 74→            Write-Info "Adding the Entire Scoop bucket..."
 75→            & "scoop" bucket add entire $ScoopBucketUrl
 76→            if ($LASTEXITCODE -ne 0) {
 77→                throw "Failed to add the Entire Scoop bucket."
 78→            }
 79→        }
 80→
 81→        & "scoop" prefix entire *> $null
 82→        $isInstalled = $LASTEXITCODE -eq 0
 83→        if ($isInstalled) {
 84→            Write-Info "Updating Entire CLI with Scoop..."
 85→            & "scoop" update entire/entire
 86→        }
 87→        else {
 88→            Write-Info "Installing Entire CLI with Scoop..."
 89→            & "scoop" install entire/entire
 90→        }
 91→
 92→        if ($LASTEXITCODE -ne 0) {
 93→            throw "Scoop failed to install Entire CLI."
 94→        }
 95→
 96→        Write-Success "Entire CLI installed with Scoop"
 97→    }
