 99→    function Get-PlatformArchitecture {
100→        # PROCESSOR_ARCHITEW6432 identifies the native OS architecture when
101→        # this script is running in a 32-bit PowerShell process.
102→        $architecture = $env:PROCESSOR_ARCHITEW6432
103→        if ([string]::IsNullOrWhiteSpace($architecture)) {
104→            $architecture = $env:PROCESSOR_ARCHITECTURE
105→        }
106→
107→        if ([string]::IsNullOrWhiteSpace($architecture)) {
108→            throw "Cannot determine the Windows architecture."
109→        }
110→
111→        switch ($architecture.ToUpperInvariant()) {
112→            { $_ -in @("AMD64", "X86_64") } { return "amd64" }
113→            { $_ -in @("ARM64", "AARCH64") } { return "arm64" }
114→            default { throw "Unsupported architecture: $architecture" }
115→        }
116→    }
