118→    function Invoke-GitHubApi {
119→        param([string] $Uri)
120→
121→        $headers = @{
122→            "Accept"     = "application/vnd.github+json"
123→            "User-Agent" = "entire-install.ps1"
124→        }
125→        if (-not [string]::IsNullOrWhiteSpace($env:GITHUB_TOKEN)) {
126→            $headers["Authorization"] = "Bearer $($env:GITHUB_TOKEN)"
127→        }
128→
129→        Invoke-RestMethod -Uri $Uri -Headers $headers -UseBasicParsing
130→    }
