132→    function Get-ReleaseVersion {
133→        param([string] $ReleaseChannel)
134→
135→        if ($ReleaseChannel -eq "nightly") {
136→            $uri = "https://api.github.com/repos/$GitHubRepo/releases?per_page=20"
137→            $releases = Invoke-GitHubApi -Uri $uri
138→            $release = $null
139→
140→            # Windows PowerShell 5.1 returns a JSON array from
141→            # Invoke-RestMethod as one pipeline object. A Where-Object pipeline
142→            # would therefore test the whole release list at once instead of
143→            # each release, so enumerate it explicitly.
144→            foreach ($candidate in $releases) {
145→                if ($candidate.tag_name -like "*nightly*") {
146→                    $release = $candidate
147→                    break
148→                }
149→            }
150→        }
151→        else {
152→            $uri = "https://api.github.com/repos/$GitHubRepo/releases/latest"
153→            $release = Invoke-GitHubApi -Uri $uri
154→        }
155→
156→        if ($null -eq $release -or [string]::IsNullOrWhiteSpace([string] $release.tag_name)) {
157→            throw "Failed to fetch the latest $ReleaseChannel version from GitHub. Check your internet connection."
158→        }
159→
160→        $version = ([string] $release.tag_name) -replace "^v", ""
161→        if ($version -notmatch "^[0-9]+\.[0-9]+\.[0-9]+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$") {
162→            throw "GitHub returned an invalid release version: $version"
163→        }
164→
165→        return $version
166→    }
