177→    function Assert-Checksum {
178→        param(
179→            [string] $ArchivePath,
180→            [string] $ArchiveName,
181→            [string] $ChecksumsPath
182→        )
183→
184→        $escapedArchiveName = [regex]::Escape($ArchiveName)
185→        $checksumLine = Get-Content -LiteralPath $ChecksumsPath |
186→            Where-Object { $_ -match "(?i)^[0-9a-f]{64}\s+\*?$escapedArchiveName\s*$" } |
187→            Select-Object -First 1
188→
189→        if ([string]::IsNullOrWhiteSpace([string] $checksumLine)) {
190→            throw "Checksum for $ArchiveName was not found in checksums.txt."
191→        }
192→
193→        $expectedChecksum = ([string] $checksumLine -split "\s+")[0]
194→        $actualChecksum = (Get-FileHash -LiteralPath $ArchivePath -Algorithm SHA256).Hash
195→        if (-not [string]::Equals($actualChecksum, $expectedChecksum, [StringComparison]::OrdinalIgnoreCase)) {
196→            throw "Checksum verification failed. Expected: $expectedChecksum, actual: $actualChecksum"
197→        }
198→    }
