200→    function Get-NormalizedPath {
201→        param([string] $Path)
202→
203→        return [IO.Path]::GetFullPath($Path).TrimEnd([IO.Path]::DirectorySeparatorChar)
204→    }
205→
206→    function Test-SamePath {
207→        param(
208→            [string] $Left,
209→            [string] $Right
210→        )
211→
212→        if ([string]::IsNullOrWhiteSpace($Left) -or [string]::IsNullOrWhiteSpace($Right)) {
213→            return $false
214→        }
215→
216→        try {
217→            return [string]::Equals(
218→                (Get-NormalizedPath -Path $Left),
219→                (Get-NormalizedPath -Path $Right),
220→                [StringComparison]::OrdinalIgnoreCase
221→            )
222→        }
223→        catch {
224→            return $false
225→        }
226→    }
227→
228→    function Test-PathContains {
229→        param(
230→            [AllowNull()]
231→            [string] $PathValue,
232→            [string] $Directory
233→        )
234→
235→        if ([string]::IsNullOrWhiteSpace($PathValue)) {
236→            return $false
237→        }
238→
239→        foreach ($entry in ($PathValue -split ";")) {
240→            if (Test-SamePath -Left $entry.Trim() -Right $Directory) {
241→                return $true
242→            }
243→        }
244→        return $false
245→    }
246→
247→    function Add-ToUserPath {
248→        param([string] $Directory)
249→
250→        $userPath = [Environment]::GetEnvironmentVariable("Path", "User")
251→        if (-not (Test-PathContains -PathValue $userPath -Directory $Directory)) {
252→            if ([string]::IsNullOrWhiteSpace($userPath)) {
253→                $newUserPath = $Directory
254→            }
255→            else {
256→                $newUserPath = "$Directory;$userPath"
257→            }
258→            [Environment]::SetEnvironmentVariable("Path", $newUserPath, "User")
259→        }
260→
261→        # Make the command available immediately when install.ps1 is evaluated
262→        # in the caller's current PowerShell process.
263→        if (-not (Test-PathContains -PathValue $env:Path -Directory $Directory)) {
264→            $env:Path = "$Directory;$($env:Path)"
265→        }
266→    }
