268→    function Install-Entire {
269→        if ($ShowHelp) {
270→            Write-Usage
271→            return
272→        }
273→
274→        Write-Info "Installing Entire CLI..."
275→
276→        $scoopCommand = Get-Command "scoop" -ErrorAction SilentlyContinue
277→        if ($SelectedChannel -eq "stable" -and $null -ne $scoopCommand) {
278→            Install-EntireWithScoop
279→            return
280→        }
281→        if ($SelectedChannel -eq "nightly" -and $null -ne $scoopCommand) {
282→            Write-InstallerWarning "Scoop only publishes stable releases; installing nightly from the verified release archive."
283→        }
284→
285→        # GitHub requires TLS 1.2. Use the numeric value so this remains valid
286→        # on .NET versions whose SecurityProtocolType enum omits the name.
287→        [Net.ServicePointManager]::SecurityProtocol =
288→            [Net.ServicePointManager]::SecurityProtocol -bor 3072
289→
290→        $architecture = Get-PlatformArchitecture
291→        Write-Info "Detected platform: windows/$architecture"
292→
293→        Write-Info "Fetching latest $SelectedChannel version..."
294→        $version = Get-ReleaseVersion -ReleaseChannel $SelectedChannel
295→        Write-Info "Installing version: $version"
296→
297→        $archiveName = "entire_windows_$architecture.zip"
298→        $releaseBaseUrl = "https://github.com/$GitHubRepo/releases/download/v$version"
299→        $downloadUrl = "$releaseBaseUrl/$archiveName"
300→        $checksumsUrl = "$releaseBaseUrl/checksums.txt"
301→
302→        $tempDir = Join-Path ([IO.Path]::GetTempPath()) ("entire-install-" + [guid]::NewGuid().ToString("N"))
303→        New-Item -ItemType Directory -Path $tempDir | Out-Null
304→
305→        try {
306→            $archivePath = Join-Path $tempDir $archiveName
307→            $checksumsPath = Join-Path $tempDir "checksums.txt"
308→            $extractDir = Join-Path $tempDir "extracted"
309→
310→            Write-Info "Downloading $archiveName..."
311→            Save-RemoteFile -Uri $downloadUrl -Destination $archivePath
312→
313→            Write-Info "Downloading checksums..."
314→            Save-RemoteFile -Uri $checksumsUrl -Destination $checksumsPath
315→
316→            Write-Info "Verifying checksum..."
317→            Assert-Checksum -ArchivePath $archivePath -ArchiveName $archiveName -ChecksumsPath $checksumsPath
318→            Write-Success "Checksum verified"
319→
320→            Write-Info "Extracting..."
321→            Expand-Archive -LiteralPath $archivePath -DestinationPath $extractDir -Force
322→
323→            $sourceBinary = Join-Path $extractDir "entire.exe"
324→            $sourceHelper = Join-Path $extractDir "git-remote-entire.exe"
325→            if (-not (Test-Path -LiteralPath $sourceBinary -PathType Leaf)) {
326→                throw "entire.exe was not found in $archiveName."
327→            }
328→
329→            $resolvedInstallDir = Get-NormalizedPath -Path $SelectedInstallDir
330→            Write-Info "Installing to $resolvedInstallDir..."
331→            New-Item -ItemType Directory -Path $resolvedInstallDir -Force | Out-Null
332→
333→            $installPath = Join-Path $resolvedInstallDir "entire.exe"
334→            Copy-Item -LiteralPath $sourceBinary -Destination $installPath -Force
335→
336→            if (Test-Path -LiteralPath $sourceHelper -PathType Leaf) {
337→                Copy-Item -LiteralPath $sourceHelper -Destination (Join-Path $resolvedInstallDir "git-remote-entire.exe") -Force
338→            }
339→            else {
340→                Write-InstallerWarning "git-remote-entire.exe was not found in the archive; entire:// clones will not work until the next release includes it."
341→            }
342→
343→            & $installPath version *> $null
344→            if ($LASTEXITCODE -ne 0) {
345→                throw "Installation completed, but entire.exe failed to execute."
346→            }
347→            Write-Success "Entire CLI installed to $installPath"
348→
349→            $pathCommand = Get-Command "entire" -CommandType Application -ErrorAction SilentlyContinue |
350→                Select-Object -First 1
351→            if ($null -ne $pathCommand -and -not (Test-SamePath -Left $pathCommand.Source -Right $installPath)) {
352→                Write-Host ""
353→                Write-Host "! WARNING: PATH conflict detected" -ForegroundColor Yellow
354→                Write-Host "!"
355→                Write-Host "! Installed to: $installPath"
356→                Write-Host "! But 'entire' resolves to: $($pathCommand.Source)"
357→                Write-Host "!"
358→                Write-Host "! Remove the old installation or adjust PATH to prioritize:"
359→                Write-Host "!   $resolvedInstallDir"
360→                Write-Host ""
361→                throw "Installation completed, but PATH needs adjustment."
362→            }
363→
364→            if ($SkipPathUpdate) {
365→                if ($null -eq $pathCommand) {
366→                    Write-InstallerWarning "$resolvedInstallDir is not on PATH. Add it before running entire."
367→                }
368→            }
369→            else {
370→                Add-ToUserPath -Directory $resolvedInstallDir
371→                if ($null -eq $pathCommand) {
372→                    Write-Success "Added $resolvedInstallDir to your user PATH"
373→                    Write-Host "Restart your terminal, then run entire to get started."
374→                }
375→            }
376→        }
377→        finally {
378→            Remove-Item -LiteralPath $tempDir -Recurse -Force -ErrorAction SilentlyContinue
379→        }
380→    }
381→
382→    try {
383→        Install-Entire
384→    }
385→    catch {
386→        Write-Host "Error: $($_.Exception.Message)" -ForegroundColor Red
387→        throw
388→    }
389→} $Channel $InstallDir $NoPathUpdate.IsPresent $Help.IsPresent
390→

